#include <iostream>
#include <vector>

class Instrument {
public:
    virtual ~Instrument() = default;               // virtual destructor!
    virtual double pv() const { return 0.0; }
};

class Bond : public Instrument {
public:
    explicit Bond(double pv) : pv_{pv} {}
    double pv() const override { return pv_; }
private:
    double pv_;
};

class Option : public Instrument {
public:
    explicit Option(double pv) : pv_{pv} {}
    double pv() const override { return pv_; }
private:
    double pv_;
};

int main() {
    std::vector<Instrument*> book{new Bond{1000.0}, new Option{42.5}};
    double total = 0.0;
    for (const Instrument* i : book) total += i->pv();   // dynamic dispatch
    std::cout << total << '\n';                          // 1042.5
    for (Instrument* i : book) delete i;                 // safe: virtual dtor
}

