guidedExercise.solution:
Total: $50000 + 5312.25 \times 20 = 50000 + 106245 = 156245$. The deletes are safe because ~Instrument is virtual: delete dispatches to ~Future and the whole chain runs, derived first.

```cpp
#include <iostream>
#include <vector>

class Instrument {
public:
    virtual ~Instrument() = default;
    virtual double value() const = 0;   // abstract interface
};

class Cash : public Instrument {
public:
    explicit Cash(double amount) : amount_{amount} {}
    double value() const override { return amount_; }
private:
    double amount_;
};

class Future : public Instrument {
public:
    Future(double price, double multiplier) : price_{price}, mult_{multiplier} {}
    double value() const override { return price_ * mult_; }
private:
    double price_, mult_;
};

int main() {
    std::vector<Instrument*> book{new Cash{50000.0}, new Future{5312.25, 20.0}};
    double total = 0.0;
    for (const Instrument* i : book) total += i->value();
    std::cout << total << '\n';        // 156245
    for (Instrument* i : book) delete i;   // virtual dtor: safe
}
```

independentExercise.prompt:
The program below compiles but prints 0 instead of 59.5, and its cleanup is broken. Identify both bugs, fix them minimally, and name the rule each bug breaks.

```cpp
#include <iostream>
#include <vector>

class Instrument {
public:
    ~Instrument() {}                    // bug lives here too
    double pv() const { return 0.0; }   // and here
};

class Option : public Instrument {
public:
    explicit Option(double pv) : pv_{pv} {}
    double pv() const { return pv_; }   // hides the base function
private:
    double pv_;
};

int main() {
    std::vector<Instrument*> book{new Option{42.5}, new Option{17.0}};
    double total = 0.0;
    for (const Instrument* i : book) total += i->pv();
    std::cout << total << '\n';          // prints 0, not 59.5
    for (Instrument* i : book) delete i; // and this is worse than a leak
}
```

independentExercise.solution:
Bug 1: `pv()` is not virtual, so `i->pv()` binds **statically** to Instrument::pv() and returns 0.0 for every element, the sum prints 0. Mark it `virtual` in Instrument (and add `override` in Option). Bug 2: `~Instrument()` is not virtual, so `delete` through `Instrument*` is **undefined behaviour**; typically the derived destructor never runs. Give Instrument a `virtual ~Instrument() = default;`. Fixed, the program prints 59.5 ($42.5 + 17.0$) and destroys both Options cleanly. Rules: only virtual functions bind dynamically through base pointers/references; polymorphic bases need virtual destructors.

```cpp
class Instrument {
public:
    virtual ~Instrument() = default;
    virtual double pv() const { return 0.0; }
};

class Option : public Instrument {
public:
    explicit Option(double pv) : pv_{pv} {}
    double pv() const override { return pv_; }
private:
    double pv_;
};
```

